const TEE_COLORS = { Gold: '#E3B440', Green: '#57A263', White: '#F3EEDF', Orange: '#F58A70' };
const GRAD = (id, x1, y1, x2, y2) => '<linearGradient id="' + id + '" x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '"><stop offset="0" stop-color="#25403A"/><stop offset="1" stop-color="#25403A" stop-opacity="0"/></linearGradient>';

// Returns an <svg> string for course hole n (1-9).
export function holeSvg(n) {
  const h = HOLE_DATA[n];
  if (!h) return '';
  const L = h.layers, r = h.route, tee = r[0], pin = r[r.length - 1];
  const pts = r.map((p) => p.join(',')).join(' ');
  const flag = 'M' + pin[0] + ',' + (pin[1] - 22) + 'L' + (pin[0] + 17) + ',' + (pin[1] - 15) + 'L' + pin[0] + ',' + (pin[1] - 8) + 'Z';
  const id = 'hz' + n;
  return '<svg class="holemap" viewBox="0 0 378 702" role="img" aria-label="Layout of course hole ' + n + ', tee at the bottom, green at the top">' +
    '<defs><pattern id="' + id + 'm" width="26" height="26" patternUnits="userSpaceOnUse"><rect width="13" height="26" fill="#fff" fill-opacity="0.05"/></pattern>' +
    GRAD(id + 't', 0, 0, 0, 1) + GRAD(id + 'b', 0, 1, 0, 0) + GRAD(id + 'l', 0, 0, 1, 0) + GRAD(id + 'r', 1, 0, 0, 0) + '</defs>' +
    '<rect width="378" height="702" fill="#1F3D2C"/>' +
    '<path fill="#2B5538" fill-rule="evenodd" d="' + L.BASE + '"/>' +
    '<path fill="#3C7A4A" fill-rule="evenodd" d="' + L.FAIR + '"/><path fill="url(#' + id + 'm)" fill-rule="evenodd" d="' + L.FAIR + '"/>' +
    '<path fill="#67AE70" fill-rule="evenodd" d="' + L.TEE + '"/>' +
    '<path fill="#4F86B0" stroke="#37698F" stroke-width="1.5" stroke-linejoin="round" fill-rule="evenodd" d="' + L.WATER + '"/>' +
    '<path fill="none" stroke="#57A263" stroke-width="9" stroke-opacity="0.75" stroke-linejoin="round" d="' + L.GREEN + '"/>' +
    '<path fill="#E9D8A6" stroke="#C2A96A" stroke-width="1" stroke-linejoin="round" fill-rule="evenodd" d="' + L.SAND + '"/>' +
    '<path fill="#8FD18B" stroke="#BDEBB6" stroke-width="1.5" stroke-linejoin="round" fill-rule="evenodd" d="' + L.GREEN + '"/>' +
    '<polyline points="' + pts + '" fill="none" stroke="#25403A" stroke-opacity="0.45" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<polyline points="' + pts + '" fill="none" stroke="#F58A70" stroke-width="2.5" stroke-dasharray="7 7" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<circle cx="' + tee[0] + '" cy="' + tee[1] + '" r="5.5" fill="#F58A70" stroke="#25403A" stroke-width="2"/>' +
    '<path d="M' + pin[0] + ',' + (pin[1] - 22) + 'L' + pin[0] + ',' + pin[1] + '" stroke="#F3EEDF" stroke-width="2" stroke-linecap="round"/>' +
    '<path d="' + flag + '" fill="#F58A70" stroke="#25403A" stroke-width="1" stroke-linejoin="round"/>' +
    '<circle cx="' + pin[0] + '" cy="' + pin[1] + '" r="3.5" fill="#F3EEDF" stroke="#25403A" stroke-width="1.5"/>' +
    '<rect width="378" height="50" fill="url(#' + id + 't)"/><rect y="660" width="378" height="42" fill="url(#' + id + 'b)"/>' +
    '<rect width="34" height="702" fill="url(#' + id + 'l)"/><rect x="344" width="34" height="702" fill="url(#' + id + 'r)"/>' +
    '<text x="' + (tee[0] + 12) + '" y="' + (tee[1] + 18) + '" class="hm-l">TEE</text></svg>';
}

// Tee yardages for a hole, in play order of the tee list: [{ tee, yds, color }]
export function teeYards(course, n) {
  return Object.keys(course.tees).map((t) => ({ tee: t, yds: course.tees[t].yards ? course.tees[t].yards[n - 1] : null, color: TEE_COLORS[t] || '#F3EEDF' }));
}
